import sys

def find_year(abbreviation):
    suffix = abbreviation[4:]
    length = len(suffix)
    for year in range(1989, 10000):
        if str(year)[-length:] == suffix:
            return year

n = int(input().strip())
abbreviations = [input().strip() for _ in range(n)]
years = [find_year(abbr) for abbr in abbreviations]
for year in years:
    print(year)
